class Solution {
  public List<Integer> maxActiveSectionsAfterTrade(String s, int[][] queries) {
    int n = s.length();
    int[] ones = new int[n + 1];
    for (int i = 0; i < n; i++) ones[i + 1] = ones[i] + (s.charAt(i) == '1' ? 1 : 0);
    int[] zs = new int[n], ze = new int[n];
    int z = 0;
    for (int i = 0; i < n; ) {
      if (s.charAt(i) == '1') {
        i++;
        continue;
      }
      int j = i;
      while (j < n && s.charAt(j) == '0') j++;
      zs[z] = i;
      ze[z++] = j - 1;
      i = j;
    }
    int pairs = Math.max(0, z - 1);
    int LOG = 1;
    while ((1 << LOG) <= Math.max(pairs, 1)) LOG++;
    int[][] sp = new int[LOG][Math.max(pairs, 1)];
    for (int i = 0; i < pairs; i++) sp[0][i] = (ze[i] - zs[i] + 1) + (ze[i + 1] - zs[i + 1] + 1);
    for (int j = 1; j < LOG; j++) {
      for (int i = 0; i + (1 << j) <= pairs; i++) {
        sp[j][i] = Math.max(sp[j - 1][i], sp[j - 1][i + (1 << (j - 1))]);
      }
    }
    List<Integer> res = new ArrayList<>();
    for (int[] q : queries) {
      int l = q[0], r = q[1];
      int base = ones[n];
      int lo = 0, hi = z;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (ze[mid] >= l) hi = mid;
        else lo = mid + 1;
      }
      int a = lo;
      lo = -1;
      hi = z - 1;
      while (lo < hi) {
        int mid = (lo + hi + 1) >>> 1;
        if (zs[mid] <= r) lo = mid;
        else hi = mid - 1;
      }
      int b = lo, gain = 0;
      if (b > a) {
        int lenA = Math.min(ze[a], r) - Math.max(zs[a], l) + 1;
        int lenB = Math.min(ze[b], r) - Math.max(zs[b], l) + 1;
        if (b == a + 1) {
          gain = lenA + lenB;
        } else {
          gain = Math.max(lenA + (ze[a + 1] - zs[a + 1] + 1), lenB + (ze[b - 1] - zs[b - 1] + 1));
          int from = a + 1, to = b - 2;
          if (from <= to) {
            int k = 31 - Integer.numberOfLeadingZeros(to - from + 1);
            gain = Math.max(gain, Math.max(sp[k][from], sp[k][to - (1 << k) + 1]));
          }
        }
      }
      res.add(base + gain);
    }
    return res;
  }
}
